import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def f(g):
    h,w=len(g),len(g[0])
    # find separator row or column of uniform nonzero single color distinct from blocks
    sep=None
    for i,row in enumerate(g):
        if len(set(row))==1 and row[0] not in (0,4,5) and any(row[0]==c for c in (3,)):
            sep=('row',i)
    if sep:
        i=sep[1]; A=[r[:] for r in g[:i]]; B=[r[:] for r in g[i+1:]]
        return [[2 if (a!=0 and b!=0) else 0 for a,b in zip(ra,rb)] for ra,rb in zip(A,B)]
    # column separator
    for j in range(w):
        col=[g[i][j] for i in range(h)]
        if len(set(col))==1 and col[0] not in (0,1,9):
            A=[r[:j] for r in g]; B=[r[j+1:] for r in g]
            return [[2 if (a!=0 and b!=0) else 0 for a,b in zip(ra,rb)] for ra,rb in zip(A,B)]
d=G['Demo pair 1 input']
out=f(d)
print(out==G['Demo pair 1 output'])
print(json.dumps(f(G['Test input'])))
